import pandas as pd
import openpyxl

# Try to read with openpyxl to preserve formulas
wb = openpyxl.load_workbook('/tmp/embedded.xlsx', data_only=False)
ws = wb.active

print('Worksheet name:', ws.title)
print('\\n=== Sheet content (with formulas) ===')
for row in ws.iter_rows(values_only=False):
    row_data = []
    for cell in row:
        if cell.value is not None:
            if hasattr(cell, 'data_type') and cell.data_type == 'f':
                # It's a formula
                row_data.append(f'FORMULA:{cell.value}')
            else:
                row_data.append(str(cell.value))
    if row_data:
        print('\\t'.join(row_data))

print('\\n=== Sheet content (evaluated values) ===')
wb_vals = openpyxl.load_workbook('/tmp/embedded.xlsx', data_only=True)
ws_vals = wb_vals.active
for row in ws_vals.iter_rows(values_only=True):
    row_data = []
    for cell in row:
        if cell is not None:
            row_data.append(str(cell))
    if row_data:
        print('\\t'.join(row_data))
